#stage { --ground:#F6EDC8; --main:#7A5A3F; --second:#2B2420; --accent:#8DB37E; color:var(--second); font-family:var(--sans, system-ui, sans-serif) }
.ground { position:absolute; inset:0; background:var(--ground) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:18px } .words > * { margin:0 }
.line { font-family:var(--display, var(--sans, system-ui, sans-serif)); font-size:96px; line-height:1.02; font-weight:400 } .sub { font-size:34px }
.art { position:absolute; inset:0; width:100%; height:100%; overflow:visible }
.layer { position:absolute; inset:0 }
.hand-label { position:absolute; margin:0; font-family:var(--display, var(--sans, system-ui, sans-serif)); color:#2A2522; letter-spacing:.04em; line-height:1.05; text-transform:uppercase; font-size:72px; white-space:nowrap }
.hand-label.big { font-size:110px }
.hand-label.tag { background:#FFFDF4; border:4px solid #2A2522; border-radius:14px 22px 16px 20px; padding:10px 26px 14px; box-shadow:8px 8px 0 rgba(42,37,34,.18) }
.vignette { position:absolute; inset:0; background:radial-gradient(100% 95% at 50% 45%, transparent 62%, rgba(42,37,34,.22)) }
.fade{position:absolute;inset:0;background:#120F0D;opacity:0;pointer-events:none}
.hand-label{transform-origin:0 50%}
.cut{display:none!important}
